        let lhs = stap::oriented::Multivector::from(stap::oriented::Bivector::<(), f64, gax::Extrinsic>::from_subalgebra(x.undual()));
        let rhs = stap::oriented::Multivector::from(stap::oriented::Trivector::<(), f64, gax::Intrinsic>::from_subalgebra(x).undual());
        assert!(close(&lhs, &rhs), "Spatial undual");
